"""Assemble hash-bound classification and bounded consumer/adaptation review."""
import base64
import collections
import hashlib
import json
from pathlib import Path
import subprocess

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
P='education_demo_classification'
rows=json.loads((HERE/(P+'_draft_rows.json')).read_text(encoding='utf-8'))
refs=json.loads((HERE/(P+'_references_scoped.json')).read_text(encoding='utf-8'))
adapt=json.loads((HERE/(P+'_adaptation_plan.json')).read_text(encoding='utf-8'))
yaml_shapes={r['path']:r for r in json.loads((HERE/(P+'_yaml_shapes.json')).read_text(encoding='utf-8'))}
index={r['path']:r for r in rows}
for c in refs['consumers']:
    for p in {p for o in c['occurrences'] for p in o['targets']}:
        if p in index:index[p]['consumer_reference_ids'].append(c['id'])
for row in rows:
    if row['path'] in yaml_shapes:
        row['content_evidence']['yaml_shape']=yaml_shapes[row['path']]
        if not row['full_source_read']:row['review_depth']='parsed_yaml_shape_and_reference_role_not_full_manual_body_review'
    if row['line_count'] is None:
        row['source_evidence'][0]['lines']=[]
    row['consumer_impacts']=['Review candidate occurrences in '+P+'_references_scoped.json; module-name hits can be unrelated homonyms.','Use separate adaptation plan for confirmed navigation/import changes; retain historical custody paths/hashes.'] if row['consumer_reference_ids'] else ['No candidate occurrence found in the bounded public-text scan; absence is not proof of no dynamic or external consumers.']
    if row['disposition']=='move':
        row['consumer_impacts'].append('Preserve original bytes at proposed destination before any separately recorded adaptation; delete/move sources only through the parent migration custody process.')
    if row['group']=='historical_challenge_findings':
        row['review_depth']='notice_opening_and_report_structure_classification_not_full_empirical_reaudit'
        row['content_evidence']['classification_exception']='Explicit empirical-report/model-run structure and correction notices; group default overridden after body inspection. No reported result recertified.'

assert len(rows)==1539 and len(index)==1539
assert sum(r['disposition']=='move' for r in rows)==84
assert len({r['proposed_destination'] for r in rows if r['disposition']=='move'})==84
for row in rows:
    assert hashlib.sha256((ROOT/row['path']).read_bytes()).hexdigest()==row['sha256'],row['path']
for change in adapt['changes']:
    after=base64.b64decode(change['after_bytes_base64'])
    assert hashlib.sha256(after).hexdigest()==change['post_adaptation_sha256']
    assert len(after)==change['post_adaptation_bytes']

def ev(path,lines):return {'path':path,'sha256':index[path]['sha256'],'lines':lines}
findings=[
 {'id':'EDMOVE-01','title':'Local triangle game is a coherent demo unit','detail':'The governor computes absolute rational triangle circulation, admits annotations, enforces strict CUT descent and terminal/fuel refusals. UI and notebooks consume it locally. Keep the runtime, three notebooks, two builders, four tests and four diagrams together; do not relabel its receipt as native Phi1/Gamma2/Xi or arbitrary claim verification.','evidence':[ev('education/004_oepfp/_how_to_play/educational_governor.py',[1,176]),ev('education/004_oepfp/_how_to_play/interactive_board.py',[27,38]),ev('education/004_oepfp/_how_to_play/interactive_board.py',[542,550])]},
 {'id':'EDMOVE-02','title':'Teaching simulations are separate from production mechanisms','detail':'Operad composition only constructs profiles/names, the mirror is an in-memory dictionary, EIS affinity is token overlap plus a synthetic +0.05 mutation, and PCIV retro-inheritance manufactures improved metrics. Relocate as simulations with their tests; ordinary level lessons and Lean teaching predicates remain reference curriculum. This classification agrees with prior EDU-003/006/009 findings after fresh owner-body inspection.','evidence':[ev('education/008_oeop/code/was_operad_core.py',[50,79]),ev('education/008_oeop/code/was_operad_core.py',[240,260]),ev('education/009_oeeis/code/eis_core.py',[214,237]),ev('education/010_oepciv/code/prompt_civilization_core.py',[174,209])]},
 {'id':'EDMOVE-03','title':'Captured model replies inside scenes are pilot evidence','detail':'Track A has three stored provider-labelled reply receipts and six directly produced videos. The current scene delegates recording to pfp.infrastructure.consistency_teaching; rendering reads a supplied receipt. The three stored verdicts say CONTRADICTION and laundered=false. These are historical records, not fresh calls or proof of authenticated provider provenance. The other five Manim storyboards and their narration remain curriculum.','evidence':[ev('education/004_oepfp/curriculum/scenes/naked_prompt_launder.py',[1,45]),ev('education/004_oepfp/curriculum/scenes/_render/receipt_openrouter_gpt4omini_3cycle.json',[1,64])]},
 {'id':'EDMOVE-04','title':'Twenty level-prefixed files are empirical findings records','detail':'C043-C059 notes and three findings hubs carry model/run tables, historical working conclusions, corrections and withdrawals. Their directory/name does not make them ordinary lessons. Move all twenty intact into challenge_findings; do not remove notices or deduplicate against Atlas copies on the basis of similarity. No old score is promoted to new evidence.','evidence':[ev('education/004_oepfp/levels/level_c043_space_bunny_and_combinatorial_findings.md',[1,24]),ev('education/004_oepfp/levels/level_c044_space_bunny_and_group_findings.md',[1,24]),ev('education/004_oepfp/levels/level_challenge_findings_readme.md',[1,24]),ev('education/004_oepfp/levels/level_symbol_game_challenge_and_demos_findings.md',[1,24])]},
 {'id':'EDMOVE-05','title':'Curriculum notebooks and mathematical crosswalks remain lessons','detail':'The system-integration README defines a sequenced 20-notebook learning path, exercises, a headless receipt and an explicit 125-lesson historical scaffold. The 223 curriculum notebooks and six curriculum inventories/validation receipts stay with their lesson texts. Stubs, unsupported claims, old imports and embedded outputs remain audit issues; no universal execution/completeness claim is made. docs/23_finite_qm_workflow_walkthrough.md is explicitly a classroom walkthrough and remains, with links repaired.','evidence':[ev('education/004_oepfp/curriculum/README.md',[28,103]),ev('education/004_oepfp/docs/23_finite_qm_workflow_walkthrough.md',[19,35])]},
 {'id':'EDMOVE-06','title':'Custody and runnable-path adaptations are separate','detail':'Known external consumers include two PFP test files and challenge_suite/protocol_collation.py. Game notebooks/builders contain retired education/documentation roots. Adaptation plan carries exact post bytes and hashes; no historical result JSON or dag audit receipt is rewritten. The old ten-route generator is stale relative to the checked-in notebook and must not be regenerated as a validation step. Native host/render/provider paths were not run.','evidence':[ev('education/004_oepfp/_how_to_play/build_ten_routes_notebook.py',[25,34]),ev('education/004_oepfp/curriculum/scenes/three_cycle_phi1.py',[32,47])]},
]
groups=[]
for group,number in collections.Counter(r['group'] for r in rows).items():
    sample=next(r for r in rows if r['group']==group)
    groups.append({'id':group,'count':number,'disposition':sample['disposition'],'assessment':sample['reason']})
report={'schema_version':1,'status':'classification_complete_read_only','source_commit_at_classification':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'scope':{'root':'education/','tracked_paths':1539,'roots':dict(collections.Counter(r['path'].split('/')[1] for r in rows)),'moves':84,'retains':1455,'source_mutations_performed':0,'full_every_file_mathematical_review':False,'inventory_method':'All 1539 tracked bytes SHA256-bound. All text extracted for headings/openings/references; all 226 notebooks parsed into every cell/output; all 54 YAML parsed safely; JSON roles/shapes and SVG text labels inspected structurally. Selected primary owner bodies and report notices manually reviewed. This is content-aware relocation classification, not an assertion of full manual reading of every file.'},'groups':groups,'findings':findings,'files':rows,'consumer_scan':{'artifact':P+'_references_scoped.json','scanned_files':refs['scanned_files'],'candidate_consumers':len(refs['consumers']),'method':refs['method'],'excluded_counts':refs['excluded_counts'],'false_positive_boundary':'Generic antimorphism/seal_packet names refer to several unrelated production owners; candidate hits alone are not dependency proof. Confirmed repairs are enumerated separately in the adaptation plan.'},'adaptations':{'artifact':P+'_adaptation_plan.json','patch':P+'_adaptations.patch','status':'prepared_not_applied','files':len(adapt['changes']),'navigation_repairs':len(adapt['navigation_repairs']),'contains_exact_post_bytes_and_hashes':True},'validation':{'fresh_model_calls':0,'fresh_native_calls':0,'fresh_media_renders':0,'fresh_source_test_runs':0,'checks_completed':['1539 unique paths and exact current SHA256 matches','84 unique proposed destinations and 1455 retain rows','Every adaptation after_bytes_base64 decodes to its declared byte count and SHA256','All notebooks parsed without execution; all 54 YAML safely parsed'],'practical_parent_commands':['.venv/Scripts/python.exe -B -X utf8 dag/migrations/education_demo_classification_finalize.py (before source moves only; rechecks frozen originals)','After byte relocation, verify all 84 destination hashes and absence of original moved paths against files[]; archive every original that will receive adaptation.','Apply reviewed exact after_bytes_base64 only if post_move_path still hashes to original_sha256; verify post_adaptation_sha256 afterward.','Parse adapted Python with ast.parse and adapted notebooks with json.loads; compare notebook outputs/execution_count to archived originals; do not execute notebook cells.','For bounded optional runtime verification, run only educational_governor scenario/boundary tests after reviewing current test harness imports; no generators, native-backed Track A renderers or provider notebooks.']},'limitations':['27 binary assets are hash/owner-reference classified without media rendering or audio inspection. SVG labels/XML parsing is not a visual review.','Most prose and generated notebook bodies have automated structure/content dispositions, not full manual read receipts. Explicit full_source_read and reviewed_lines fields are the only fresh full-body credit.','Ordinary lessons that describe demos remain in education; only concrete runnable companion units, direct operational runbooks and actual historical result records are moved.','No new workflow family is created solely for a teaching domain; all proposed destinations are under pilots/education.','This repository already owns education. This plan neither deletes another repository copy nor authorizes semantic deduplication.','Existing missing historical paths, unsupported empirical conclusions, optional native dependencies and the stale notebook generator are preserved and reported, not repaired into cleaner-looking evidence.','Prior education audit used for context: dag/reviews/additional_education.json; old receipts are not freshly rerun.','OPERADS remaining scope remains checkpointed separately at dag/reviews/additional_operads_core_remaining_remaining_scope.json.']}
(HERE/(P+'.json')).write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
md=['# Education demo classification','',f'All 1,539 tracked education paths classified: **84 proposed moves, 1,455 retains**. No source file was moved, edited or deleted by this review.','', 'The JSON contains one SHA-256-bound disposition, reason, review-depth label, content evidence and consumer-reference list per path. This is a content-aware relocation review, not a full mathematical audit of every lesson.','', '| Group | Files | Disposition |','| --- | ---: | --- |']
md += [f"| {g['id']} | {g['count']} | {g['disposition']} |" for g in groups]
md += ['', '## Findings','']
for finding in findings:
    md += [f"**{finding['id']}: {finding['title']}.** {finding['detail']}",'']
md += ['## Consumer repair and validation','',f"The separate adaptation plan prepares {len(adapt['changes'])} file changes and {len(adapt['navigation_repairs'])} resolved navigation repairs. It contains exact post bytes (base64), pre/post SHA-256 values and a review patch. Relocate unchanged bytes first, verify custody, archive modification originals, then apply adaptations as separately recorded changes. Nothing has been applied.",'', 'Known runtime consumers are `pfp/tests/test_consistency_teaching.py`, `pfp/tests/finite_qm_workflow/test_finite_qm_reference_workflow.py`, and `workflows/wf19_failure_derived_rule_transfer/pilots/challenge_suite/protocol_collation.py`. Generic module-word matches in the wider census are candidate references, often unrelated homonyms.','', 'The local game runtime uses sibling discovery, and simulation conftests retain the same code/tests depth. Track A keeps sibling `_render` and `antimorphism.py`; its repository search generally survives the move. The three-cycle archive fallback and optional native dependencies are pre-existing limitations. The ten-route builder refers to a retired packet-demo owner while the checked-in notebook embeds a checker: do not regenerate notebooks during relocation.','', 'Before migration, run the prefixed finalizer to verify all original hashes. After migration, verify all destinations against the frozen map, apply only hash-matching adaptation bytes, parse Python/JSON without importing source, and check every declared navigation target in the planned tree. No model, native, generator or media execution is required for this move.','', '## Depth and exclusions','']
md += [f'- {s}' for s in report['limitations']]
(HERE/(P+'.md')).write_text('\n'.join(md)+'\n',encoding='utf-8')
print('classification written',len(rows),'paths; moves',84,'retains',1455,'adaptations',len(adapt['changes']))
print('classification_sha256',hashlib.sha256((HERE/(P+'.json')).read_bytes()).hexdigest())
print('adaptation_sha256',hashlib.sha256((HERE/(P+'_adaptation_plan.json')).read_bytes()).hexdigest())
